mapper.select:
SELECT HR.PERSON_ID, HR.EMPID, HR.LOCAL_NAME, HR.DEPTNO, GET_DEPT_NAME(HR.DEPTNO, #{lang, jdbcType=VARCHAR}) AS DEPT_NAME, HR.POST_GRADE_NO, GET_GLOBAL_NAME(HR.POST_GRADE_NO, #{lang, jdbcType=VARCHAR}) AS POST_NAME, GET_GLOBAL_NAME(HR.SHIFT_NO, #{lang, jdbcType=VARCHAR}) AS SHIFT_NAME, NVL(GET_AR_OT_TOTAIL_INTERVAL(, , HR.CPNY_ID, HR.PERSON_ID, '200'), 0) AS OT_TOTAL, NVL(GET_AR_OT_TOTAIL_INTERVAL(, , HR.CPNY_ID, HR.PERSON_ID, '141444'), 0) AS WEEKDAY_OT_TOTAL, NVL(GET_AR_OT_TOTAIL_INTERVAL(, , HR.CPNY_ID, HR.PERSON_ID, '141445'), 0) AS WEEKEND_OT_TOTAL, NVL(GET_AR_OT_TOTAIL_INTERVAL(, , HR.CPNY_ID, HR.PERSON_ID, '141446'), 0) AS HOLIDAY_OT_TOTAL, NVL(GET_AR_OT_TOTAIL_INTERVAL(, , HR.CPNY_ID, HR.PERSON_ID, '315'), 0) AS MEAL_OT_INCEN, NVL(GET_AR_OT_TOTAIL_INTERVAL(, , HR.CPNY_ID, HR.PERSON_ID, '316'), 0) AS NIGHT_INCEN, NVL(GET_AR_OT_TOTAIL_INTERVAL(, , HR.CPNY_ID, HR.PERSON_ID, '317'), 0) AS SATURDAY_INCEN FROM HR_EMPLOYEE HR INNER JOIN HR_DEPARTMENT HD ON HR.DEPTNO = HD.DEPTNO WHERE HR.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND HR.EMPID NOT LIKE '%11111%' AND (HR.DATE_LEFT IS NULL OR TO_CHAR(HR.DATE_LEFT, 'YYYY/MM/DD') >= )
AND INSTR(',' || #{deptNos, jdbcType=VARCHAR} || ',', ',' || HR.DEPTNO || ',') > 0
AND HR.EMP_TYPE_CODE = #{empTypeCode, jdbcType=VARCHAR}
AND HR.SHIFT_NO = #{shiftNo, jdbcType=VARCHAR}
AND ( HR.EMPID LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' OR CONVERTTOUNSIGN(UPPER(HR.LOCAL_NAME)) LIKE '%' || CONVERTTOUNSIGN(UPPER(#{keyword, jdbcType=VARCHAR})) || '%' OR HR.ENGLISH_NAME LIKE '%' || #{keyword, jdbcType=VARCHAR} || '%' )
ORDER BY HR.EMPID ASC
